import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Palette roles are computed in sRGB. Contrast changes inks and boundaries,
 * never a CSS filter over the page or the user's images. */
export const palettes = [
  { id: "paper", name: "Paper", description: "Warm paper, crisp ink", light: ["#F8F6F1", "#FFFFFF", "#EEE9E1"], dark: ["#15171A", "#20242A", "#292F37"], accents: ["#F0A4CC", "#A8BC75", "#95BAE8", "#F1D369"] },
  { id: "tide", name: "Tide", description: "Clear blue, sea glass", light: ["#F1F6F9", "#FFFFFF", "#DFE9F0"], dark: ["#101B24", "#192A37", "#233947"], accents: ["#DAA8D5", "#8BC3B2", "#82BCEB", "#EFCD79"] },
  { id: "grove", name: "Grove", description: "Leaf greens, quiet light", light: ["#F4F6ED", "#FCFEF8", "#E4EADA"], dark: ["#141C15", "#213026", "#2D3D30"], accents: ["#E4A8B2", "#B1CA78", "#A5C7D9", "#E7CE85"] },
  { id: "clay", name: "Clay", description: "Terracotta, golden warmth", light: ["#FBF3EB", "#FFFCF7", "#EFDFD2"], dark: ["#211814", "#30231F", "#3F3028"], accents: ["#EDA992", "#B7C281", "#A4BCCF", "#F1CB7A"] },
  { id: "orchid", name: "Orchid", description: "Lavender, soft violet", light: ["#F7F3FA", "#FFFCFF", "#E9E0F0"], dark: ["#1B1521", "#2A2133", "#382C43"], accents: ["#D6ADEE", "#B7C993", "#A6BCEC", "#F0D18C"] },
  { id: "graphite", name: "Graphite", description: "Cool neutrals, clean focus", light: ["#F4F5F6", "#FFFFFF", "#E5E8EB"], dark: ["#111418", "#20252C", "#2C333D"], accents: ["#E9ACC5", "#B4C3A0", "#ABBEDC", "#E7CF98"] },
] as const;
export type PaletteName = typeof palettes[number]["id"];
export type AppearanceSettings = { palette: PaletteName; contrast: number };
export const defaultAppearance: AppearanceSettings = Object.freeze({ palette: "paper", contrast: 60 });

export function normalizeAppearance(value: unknown): AppearanceSettings {
  const input = value && typeof value === "object" ? value as Partial<AppearanceSettings> : {};
  return {
    palette: palettes.some(p => p.id === input.palette) ? input.palette! : defaultAppearance.palette,
    contrast: typeof input.contrast === "number" && Number.isFinite(input.contrast) ? Math.max(0, Math.min(100, input.contrast)) : defaultAppearance.contrast,
  };
}
function rgb(hex: string): number[] { return [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); }
export function mixColor(a: string, b: string, amount: number): string {
  const av = rgb(a), bv = rgb(b);
  return "#" + av.map((v, i) => Math.round(v + (bv[i] - v) * Math.max(0, Math.min(1, amount))).toString(16).padStart(2, "0")).join("");
}
export function luminance(hex: string): number {
  const channels = rgb(hex).map(v => { const c = v / 255; return c <= .04045 ? c / 12.92 : ((c + .055) / 1.055) ** 2.4; });
  return channels[0] * .2126 + channels[1] * .7152 + channels[2] * .0722;
}
export function contrastRatio(a: string, b: string): number {
  const x = luminance(a), y = luminance(b);
  return (Math.max(x, y) + .05) / (Math.min(x, y) + .05);
}
/** Nearest blend toward the mode's ink that clears every supplied surface. */
export function readableInk(seed: string, surfaces: readonly string[], target: number, dark: boolean): string {
  const end = dark ? "#FFFFFF" : "#080A0D";
  if (surfaces.every(bg => contrastRatio(seed, bg) >= target)) return seed;
  let low = 0, high = 1;
  for (let i = 0; i < 18; i++) {
    const mid = (low + high) / 2;
    if (surfaces.every(bg => contrastRatio(mixColor(seed, end, mid), bg) >= target)) high = mid;
    else low = mid;
  }
  return mixColor(seed, end, high);
}

export function appearanceTokens(settings: AppearanceSettings, mode: "light" | "dark"): Record<string, string> {
  const normalized = normalizeAppearance(settings);
  const palette = palettes.find(p => p.id === normalized.palette)!;
  const dark = mode === "dark", amount = normalized.contrast / 100;
  const [canvas, paper, inset] = palette[mode];
  const surfaces = [canvas, paper, inset];
  const seed = dark ? "#7E858E" : "#727781";
  const text = readableInk(seed, surfaces, 8 + amount * 7, dark);
  const secondary = readableInk(seed, surfaces, 5 + amount * 4, dark);
  const muted = readableInk(seed, surfaces, 4.6 + amount * 2.4, dark);
  const edge = readableInk(inset, surfaces, 3.1 + amount * 1.8, dark);
  const line = readableInk(inset, [canvas, paper], 1.45 + amount * .9, dark);
  const [pink, olive, blue, yellow] = palette.accents;
  const tint = (accent: string, weight = dark ? .12 : .13) => mixColor(paper, accent, weight);
  const selection = tint(pink, dark ? .17 : .24);
  const selectionInk = readableInk(text, [selection], 7 + amount * 3, dark);
  const accentInk = "#14171B";
  const tokens: Record<string, string> = {
    "--v-canvas": canvas, "--v-paper": paper, "--v-beige": inset,
    "--v-beige-2": mixColor(canvas, inset, .55), "--v-cream-pill": paper,
    "--v-text": text, "--v-text-2": secondary, "--v-text-3": muted,
    "--v-ink": text, "--v-ink-soft": secondary, "--v-on-ink": canvas,
    "--v-border": line, "--v-edge": edge, "--v-on-accent": accentInk,
    "--v-brand": readableInk(pink, surfaces, 4.6, dark),
    "--v-accent-ink": readableInk(pink, surfaces, 4.6 + amount * 2, dark),
    "--v-olive-ink": readableInk(olive, surfaces, 4.6 + amount * 2, dark),
    "--v-disabled-face": inset, "--v-disabled-ink": muted, "--v-disabled-edge": edge,
    "--v-disabled-fill": inset, "--btn-disabled-ink": muted, "--unavail-ink": muted,
    "--alert-ink": secondary, "--nav-group-ink": muted,
    "--v-skel-face": inset, "--v-skel-sheen": paper, "--v-skel-edge": line,
    "--sel-bg": selection, "--sel-ink": selectionInk,
    "--sel-edge": readableInk(pink, [...surfaces, selection], 3.1, dark),
    "--switch-knob": paper, "--switch-knob-on": accentInk,
    "--v-structure": "#14171B", "--on-structure": "#F9FAFC", "--structure-text": "#E2E6ED",
    "--structure-quiet": "#242931", "--structure-line": "#565D68", "--sidebar-muted": "#B4BDCA",
    "--surface-quiet": paper, "--surface-work": tint(blue), "--surface-automation": tint(yellow),
    "--surface-memory": tint(olive), "--surface-library": tint(pink), "--surface-ai": tint(blue), "--surface-alert": tint("#E88B7A"),
    "--v-danger": "#D7473C", "--v-danger-fill": "#B92D28", "--v-danger-ink": readableInk("#DB5146", surfaces, 4.6, dark),
    "--v-danger-soft": tint("#D7473C"), "--v-scrim": dark ? "rgba(0,0,0,.66)" : "rgba(19,24,32,.46)",
    "--glide-bg": "#14171B", "--glide-fg": "#F9FAFC",
    "--card": "var(--v-paper)", "--popover": "var(--v-paper)",
    "--accent-foreground": "var(--v-on-accent)", "--destructive": "var(--v-danger-fill)",
  };
  ["pink", "olive", "blue", "yellow"].forEach((tone, i) => {
    const color = palette.accents[i];
    tokens[`--v-${tone}`] = color;
    tokens[`--v-${tone}-deep`] = mixColor(color, "#14171B", .12);
    tokens[`--v-${tone}-soft`] = tint(color, dark ? .15 : .24);
  });
  ["ok", "warn", "danger", "info", "pending"].forEach((state, i) => {
    const color = [olive, yellow, "#D7473C", blue, secondary][i];
    const bg = tint(color);
    tokens[`--status-${state}-bg`] = bg;
    tokens[`--status-${state}-ink`] = readableInk(color, [bg], 5 + amount * 2, dark);
  });
  return tokens;
}

import { signatureShapePaths, type SignatureShapeName } from "@/lib/cojeev/signature-shapes";

export type OrganismKind = "profile" | "side-panel" | "dock" | "chat" | "focus" | "invite" | "dashboard";
export type AssemblyPartId = "surface" | "cover" | "avatar" | "badge" | "identity" | "stats" | "composer" | "primary" | "secondary" | "save" | "thread" | "progress" | "caption" | "participants" | `task-${number}` | `tool-${number}`;
export type AssemblyRect = { x:number; y:number; width:number; height:number; rotate?:number };
export type AssemblyContour = SignatureShapeName | "rounded" | "circle";
export const organismChoices: {value:OrganismKind;label:string;icon:string}[] = [
  {value:"profile",label:"Profile",icon:"user"}, {value:"side-panel",label:"Panel",icon:"panel-left"},
  {value:"dock",label:"Dock",icon:"layout-grid"}, {value:"chat",label:"Chat",icon:"message-circle"},
  {value:"focus",label:"Focus",icon:"timer"}, {value:"invite",label:"Invite",icon:"calendar"},
];
const shapes: AssemblyContour[] = ["scalloped-square","daisy-12","ribbon-soft","cloud-3","seed-wing","clover-soft","petal-7","cushion"];
export const floatingContour = (part:string):AssemblyContour => shapes[Array.from(part).reduce((sum,char)=>sum+char.charCodeAt(0),0)%shapes.length];
export type AssemblyGeometry = {height:number;parts:Partial<Record<AssemblyPartId,AssemblyRect>>};
export type AssemblyGeometryOptions = {profileComposer?:boolean;itemCount?:number};

/** Matching 96-point topology: the actual native surface can keep one continuous contour. */
export function assemblyContour(contour:AssemblyContour, width:number, height:number, radius=16):string {
  let points: number[][];
  if(contour!=="rounded"&&contour!=="circle") {
    const numbers=signatureShapePaths[contour].match(/-?\d+(?:\.\d+)?/g)!.map(Number);
    points=Array.from({length:96},(_,i)=>i===0?numbers.slice(0,2):numbers.slice(2+(i-1)*6+4,2+i*6));
  } else {
    const w=Math.max(1,width)/2,h=Math.max(1,height)/2,r=Math.min(radius,w,h);
    points=Array.from({length:96},(_,i)=>{
      const angle=i/96*Math.PI*2,dx=Math.cos(angle),dy=Math.sin(angle);
      if(contour==="circle")return[50+49.8*dx,50+49.8*dy];
      // Each corner keeps eight samples even on a tall panel or a very wide input.
      const quarter=Math.floor(i/24),u=(i%24)/8,W=quarter%2?h:w,H=quarter%2?w:h;
      const point=u<1?[W,(H-r)*u]:u<2?[W-r+r*Math.cos((u-1)*Math.PI/2),H-r+r*Math.sin((u-1)*Math.PI/2)]:[(W-r)*(3-u),H];
      const turn=quarter*Math.PI/2,px=point[0]*Math.cos(turn)-point[1]*Math.sin(turn),py=point[0]*Math.sin(turn)+point[1]*Math.cos(turn);
      return[50+px/w*49.8,50+py/h*49.8];
    });
  }
  return `polygon(${points.map(([x,y])=>`${x.toFixed(3)}% ${y.toFixed(3)}%`).join(",")})`;
}

/** Distinct native compositions, measured in the local stage rather than the viewport. */
export function organismGeometry(kind:OrganismKind, available:number, scattered=false, options:AssemblyGeometryOptions={}):AssemblyGeometry {
  const width=Math.max(240,Number.isFinite(available)?available:360);
  const frameWidth=Math.min(width-24,kind==="side-panel"||kind==="dashboard"?356:kind==="dock"?400:kind==="profile"||kind==="focus"?364:kind==="invite"?384:416);
  const left=(width-frameWidth)/2,pad=20,inside=frameWidth-pad*2,x=left+pad;
  const rect=(x:number,y:number,width:number,height:number,rotate=0):AssemblyRect=>({x,y,width,height,rotate});
  const parts:AssemblyGeometry["parts"]={};
  const count=Math.max(0,Math.min(4,Math.floor(Number.isFinite(options.itemCount)?options.itemCount!:3)));
  let height=454;
  if(kind==="profile"){
    height=options.profileComposer?510:454;
    Object.assign(parts,{
      surface:rect(left,20,frameWidth,height-44),cover:rect(left+8,28,frameWidth-16,124),
      avatar:rect(x,118,72,72),badge:rect(x+inside-104,168,104,24),
      identity:rect(x,212,inside,64),stats:rect(x,294,inside,40),
      primary:rect(x,356,(inside-10)/2,40),secondary:rect(x+(inside+10)/2,356,(inside-10)/2,40),
      save:rect(left+frameWidth-56,44,32,32),
    });
    if(options.profileComposer)parts.composer=rect(x,418,inside,52);
  }else if(kind==="dock"){
    height=262;
    const toolCount=count,gap=8,toolSize=Math.min(68,(frameWidth-80-Math.max(0,count-1)*gap)/Math.max(1,count));
    const lead=52,contentWidth=lead+toolCount*toolSize+Math.max(0,toolCount-1)*gap;
    const start=(width-contentWidth)/2;
    parts.identity=rect(left,40,frameWidth,32);parts.surface=rect(left,92,frameWidth,96);parts.avatar=rect(start,119,40,40);
    for(let index=0;index<toolCount;index++)parts[`tool-${index}`]=rect(start+lead+index*(toolSize+gap),106,toolSize,68);
    parts.caption=rect(left,208,frameWidth,34);
  }else if(kind==="chat"){
    height=528;
    Object.assign(parts,{
      surface:rect(left,20,frameWidth,484),avatar:rect(x,46,40,40),
      identity:rect(x+52,43,inside-92,48),save:rect(x+inside-32,48,32,32),
      badge:rect(x,104,inside,24),thread:rect(x,144,inside,242),composer:rect(x,411,inside,52),caption:rect(x,477,inside,16),
    });
  }else if(kind==="focus"){
    height=448;
    Object.assign(parts,{
      surface:rect(left,20,frameWidth,404),identity:rect(x,48,inside-64,70),cover:rect(x+inside-60,44,60,76),
      stats:rect(x,146,inside,88),progress:rect(x,259,inside,12),badge:rect(x,285,inside,40),
      primary:rect(x,342,inside-54,44),secondary:rect(x+inside-44,342,44,44),caption:rect(x,398,inside,16),
    });
  }else if(kind==="invite"){
    height=538;
    Object.assign(parts,{
      surface:rect(left,20,frameWidth,494),cover:rect(left+8,28,frameWidth-16,116),
      identity:rect(x,166,inside,88),stats:rect(x,271,inside,56),participants:rect(x,349,inside,40),
      caption:rect(x,409,inside,22),primary:rect(x,452,(inside-10)/2,44),secondary:rect(x+(inside+10)/2,452,(inside-10)/2,44),
    });
  }else{
    height=304+count*74;
    Object.assign(parts,{
      surface:rect(left,20,frameWidth,height-44),identity:rect(x,48,inside-70,70),cover:rect(x+inside-62,44,62,84),
      badge:rect(x,140,inside,24),progress:rect(x,184+count*74,inside,26),
      secondary:rect(x,218+count*74,inside,40),
    });
    for(let index=0;index<count;index++)parts[`task-${index}`]=rect(x,178+index*74,inside,64);
  }
  if(scattered){
    const entries=Object.keys(parts) as AssemblyPartId[];
    const stageHeight=Math.max(height,360),unit=Math.min(width*.21,stageHeight*.14,82);
    // Authored, uneven anchors retain identity without hydration randomness or a visible grid.
    const anchors=[
      [.23,.15,.96,-12],[.70,.13,.70,14],[.50,.34,1.20,-9],
      [.13,.44,.80,8],[.84,.48,.90,-17],[.29,.66,.67,13],
      [.70,.72,1,-8],[.13,.88,.73,18],[.57,.91,.84,-11],[.85,.90,.64,9],
    ];
    entries.forEach((part,index)=>{
      const [cx,cy,scale,rotation]=anchors[index],size=unit*scale;
      parts[part]=rect(width*cx-size/2,stageHeight*cy-size/2,size,size,rotation);
    });
    height=stageHeight;
  }
  return{height,parts};
}

/** A complete rectangular partition. Coordinates and dimensions are integer cells. */
export type BentoTile = {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
};
export type BentoLayout = {
  columns: number;
  rows: number;
  tiles: BentoTile[];
  seed: number;
};
export type BentoVariant = "classic" | "interlock";
export type BentoTemplate = "Editorial" | "Dashboard" | "Gallery" | "Showcase";
export type BentoEdit = { layout: BentoLayout; error?: string };
export type BentoSide = "left" | "right" | "top" | "bottom";
export const bentoTemplates: BentoTemplate[] = [
  "Editorial",
  "Dashboard",
  "Gallery",
  "Showcase",
];
const defaults = [
  "Make room for ideas",
  "In progress",
  "A little perspective",
  "Things worth keeping",
  "Next chapter",
  "Stay curious",
].map((label, i) => ({ id: `tile-${i + 1}`, label }));

export function validateBento(layout: BentoLayout): string | null {
  if (
    ![layout.columns, layout.rows].every(
      (n) => Number.isInteger(n) && n >= 2 && n <= 8,
    ) ||
    !Number.isSafeInteger(layout.seed)
  )
    return "Use 2–8 whole rows and columns, with an integer seed.";
  const cells = new Set<string>(),
    ids = new Set<string>();
  for (const tile of layout.tiles) {
    if (!tile.id || ids.has(tile.id) || typeof tile.label !== "string")
      return "Every tile needs a unique identity and text label.";
    ids.add(tile.id);
    if (
      ![tile.x, tile.y, tile.width, tile.height].every(Number.isInteger) ||
      tile.x < 0 ||
      tile.y < 0 ||
      tile.width < 1 ||
      tile.height < 1 ||
      tile.x + tile.width > layout.columns ||
      tile.y + tile.height > layout.rows
    )
      return "Tiles must stay inside the grid and occupy at least one cell.";
    for (let y = tile.y; y < tile.y + tile.height; y++)
      for (let x = tile.x; x < tile.x + tile.width; x++) {
        const cell = `${x},${y}`;
        if (cells.has(cell)) return "Tiles cannot overlap.";
        cells.add(cell);
      }
  }
  return cells.size === layout.columns * layout.rows
    ? null
    : "Tiles must cover the whole grid.";
}
function random(seed: number) {
  let value = seed >>> 0;
  return () => {
    value = (Math.imul(value, 1664525) + 1013904223) >>> 0;
    return value / 4294967296;
  };
}
export function generateBento(
  columns = 6,
  rows = 4,
  seed = 17,
  content: Pick<BentoTile, "id" | "label">[] = defaults,
  template: BentoTemplate = "Editorial",
): BentoLayout {
  if (
    ![columns, rows].every((n) => Number.isInteger(n) && n >= 2 && n <= 8) ||
    !Number.isSafeInteger(seed)
  )
    throw new Error("Use 2–8 whole rows and columns.");
  if (!content.length || content.length > columns * rows)
    throw new Error(
      "This grid cannot retain every tile. Increase its dimensions.",
    );
  const next = random(seed + bentoTemplates.indexOf(template) * 7919);
  const rectangles = [{ x: 0, y: 0, width: columns, height: rows }];
  while (rectangles.length < content.length) {
    const candidates = rectangles
      .map((tile, index) => ({
        tile,
        index,
        score:
          tile.width *
          tile.height *
          (template === "Gallery" ? 1 : 0.65 + next() * 0.7),
      }))
      .filter(({ tile }) => tile.width > 1 || tile.height > 1)
      .sort((a, b) => b.score - a.score);
    const { tile, index } = candidates[0];
    const vertical =
      tile.height === 1 ||
      (tile.width > 1 &&
        (template === "Dashboard"
          ? tile.width >= tile.height
          : next() < tile.width / (tile.width + tile.height)));
    const length = vertical ? tile.width : tile.height;
    const cut =
      template === "Gallery"
        ? Math.floor(length / 2)
        : 1 + Math.floor(next() * (length - 1));
    rectangles.splice(
      index,
      1,
      ...(vertical
        ? [
            { ...tile, width: cut },
            { ...tile, x: tile.x + cut, width: tile.width - cut },
          ]
        : [
            { ...tile, height: cut },
            { ...tile, y: tile.y + cut, height: tile.height - cut },
          ]),
    );
  }
  rectangles.sort((a, b) => a.y - b.y || a.x - b.x);
  const layout = {
    columns,
    rows,
    seed,
    tiles: rectangles.map((tile, i) => ({
      ...tile,
      id: content[i].id,
      label: content[i].label,
    })),
  };
  const error = validateBento(layout);
  if (error) throw new Error(error);
  return layout;
}
export function swapBentoTiles(
  layout: BentoLayout,
  first: string,
  second: string,
): BentoLayout {
  const a = layout.tiles.find((t) => t.id === first),
    b = layout.tiles.find((t) => t.id === second);
  if (!a || !b) return layout;
  return {
    ...layout,
    tiles: layout.tiles.map((t) =>
      t === a
        ? { ...t, id: b.id, label: b.label }
        : t === b
          ? { ...t, id: a.id, label: a.label }
          : t,
    ),
  };
}
/** Expand along touching edge intervals until the entire connected seam is owned. */
export function resizeBentoSeam(
  layout: BentoLayout,
  id: string,
  side: BentoSide,
  position: number,
): BentoEdit {
  const tile = layout.tiles.find((t) => t.id === id);
  if (!tile) return { layout, error: "Select a tile first." };
  const vertical = side === "left" || side === "right";
  const coordinate = vertical
    ? tile.x + (side === "right" ? tile.width : 0)
    : tile.y + (side === "bottom" ? tile.height : 0);
  const limit = vertical ? layout.columns : layout.rows;
  if (
    !Number.isInteger(position) ||
    position <= 0 ||
    position >= limit ||
    coordinate === 0 ||
    coordinate === limit
  )
    return {
      layout,
      error:
        "The outside edge stays fixed; every neighbor needs at least one cell.",
    };
  let start = vertical ? tile.y : tile.x,
    end = start + (vertical ? tile.height : tile.width);
  const edges = layout.tiles.filter((t) =>
    vertical
      ? t.x === coordinate || t.x + t.width === coordinate
      : t.y === coordinate || t.y + t.height === coordinate,
  );
  let changed = true;
  while (changed) {
    changed = false;
    for (const t of edges) {
      const a = vertical ? t.y : t.x,
        b = a + (vertical ? t.height : t.width);
      if (a < end && b > start) {
        const s = Math.min(start, a),
          e = Math.max(end, b);
        if (s !== start || e !== end) {
          start = s;
          end = e;
          changed = true;
        }
      }
    }
  }
  const delta = position - coordinate;
  const result = {
    ...layout,
    tiles: layout.tiles.map((t) => {
      const a = vertical ? t.y : t.x,
        b = a + (vertical ? t.height : t.width);
      if (a >= end || b <= start) return t;
      if (vertical) {
        if (t.x === coordinate)
          return { ...t, x: position, width: t.width - delta };
        if (t.x + t.width === coordinate)
          return { ...t, width: t.width + delta };
      } else {
        if (t.y === coordinate)
          return { ...t, y: position, height: t.height - delta };
        if (t.y + t.height === coordinate)
          return { ...t, height: t.height + delta };
      }
      return t;
    }),
  };
  const error = validateBento(result);
  return error
    ? {
        layout,
        error:
          "That seam cannot move further: every neighbor needs at least one cell.",
      }
    : { layout: result };
}
type Point = [number, number];
/** Canonical unit cubic. Reverse traversal reuses the exact same controls. */
export function bentoEdge(
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  seed: number,
  outer: boolean,
): [Point, Point, Point, Point] {
  if (x1 > x2 || y1 > y2) {
    const points = bentoEdge(x2, y2, x1, y1, seed, outer);
    return [points[3], points[2], points[1], points[0]];
  }
  const dx = x2 - x1,
    dy = y2 - y1,
    amplitude = outer
      ? 0
      : (random(seed + x1 * 73856093 + y1 * 19349663 + (dx ? 83492791 : 0))() -
          0.5) *
        0.42;
  return [
    [x1, y1],
    [x1 + dx / 3 + dy * amplitude, y1 + dy / 3 + dx * amplitude],
    [x1 + (dx * 2) / 3 + dy * amplitude, y1 + (dy * 2) / 3 + dx * amplitude],
    [x2, y2],
