export type BloomPoint = { x: number; y: number };
export type BloomParticle = BloomPoint & { vx: number; vy: number; radius: number; radiusFactor: number; angle: number; color: number };

export type BloomOptions = {
  /** Number of particles, 8–100. Default 50. */
  particleCount?: number;
  /** Particle radius in CSS pixels, 6–28. Default 15. */
  radius?: number;
  /** Playback speed, 0–2. Zero freezes the simulation. */
  speed?: number;
  /** Organic wandering force, 0–1. Default 0.5. */
  wander?: number;
  /** Velocity retained per 60Hz step, 0.8–0.98. Default 0.95. */
  damping?: number;
  /** Pointer force multiplier, 0–3. Default 1. */
  pointerAttraction?: number;
  /** Pointer attraction reach in CSS pixels, 0–600. Default 400. */
  pointerRadius?: number;
  /** Text force multiplier, 0–3. Default 1. */
  textAttraction?: number;
  /** Text attraction reach in CSS pixels, 0–400. Default 200. */
  textRadius?: number;
  /** Maximum distance for connections, 0–240 CSS pixels. Default 150. */
  connectionDistance?: number;
};

export function bloomNumber(value: number | undefined, fallback: number, min: number, max: number) {
  return Number.isFinite(value) ? Math.min(max, Math.max(min, value!)) : fallback;
}

export function normalizeBloomOptions(options: BloomOptions = {}): Required<BloomOptions> {
  return {
    particleCount: Math.round(bloomNumber(options.particleCount, 50, 8, 100)),
    radius: bloomNumber(options.radius, 15, 6, 28),
    speed: bloomNumber(options.speed, 1, 0, 2),
    wander: bloomNumber(options.wander, 0.5, 0, 1),
    damping: bloomNumber(options.damping, 0.95, 0.8, 0.98),
    pointerAttraction: bloomNumber(options.pointerAttraction, 1, 0, 3),
    pointerRadius: bloomNumber(options.pointerRadius, 400, 0, 600),
    textAttraction: bloomNumber(options.textAttraction, 1, 0, 3),
    textRadius: bloomNumber(options.textRadius, 200, 0, 400),
    connectionDistance: bloomNumber(options.connectionDistance, 150, 0, 240),
  };
}

/** Source forces integrated at 60Hz, independent of display refresh rate. */
export class BloomSimulation {
  particles: BloomParticle[] = [];
  options: Required<BloomOptions>;
  private randomState: number;
  private accumulator = 0;
  private gathering = 0;

  constructor(public width: number, public height: number, options: BloomOptions = {}, seed = 42) {
    this.options = normalizeBloomOptions(options);
    this.randomState = Number.isFinite(seed) ? seed >>> 0 : 42;
    this.configure(options);
  }

  private random() {
    this.randomState = (Math.imul(this.randomState, 1664525) + 1013904223) >>> 0;
    return this.randomState / 4294967296;
  }

  configure(options: BloomOptions) {
    this.options = normalizeBloomOptions(options);
    this.particles.length = Math.min(this.particles.length, this.options.particleCount);
    while (this.particles.length < this.options.particleCount) {
      const radiusFactor = 0.8 + this.random() * 0.5;
      this.particles.push({
        x: this.width / 2 + (this.random() - 0.5) * Math.min(100, this.width),
        y: this.height / 2 + (this.random() - 0.5) * Math.min(100, this.height),
        vx: (this.random() - 0.5) * 2, vy: (this.random() - 0.5) * 2,
        radius: this.options.radius * radiusFactor, radiusFactor,
        angle: this.random() * Math.PI * 2, color: this.particles.length % 4,
      });
    }
    for (const p of this.particles) p.radius = this.options.radius * p.radiusFactor;
  }

  resize(width: number, height: number) {
    for (const p of this.particles) {
      p.x = p.x / Math.max(1, this.width) * width;
      p.y = p.y / Math.max(1, this.height) * height;
    }
    this.width = width; this.height = height;
  }

  gather() { this.gathering = 240; }

  /** Resolve a direct command without animating, including at speed zero. */
  settle(words: BloomPoint[]) {
    for (let i = 0; i < 180; i++) this.step(words, null);
    this.accumulator = 0;
  }

  scatter() {
    this.gathering = 0;
    for (const p of this.particles) {
      const angle = this.random() * Math.PI * 2;
      const distance = 0.2 + this.random() * 0.24;
      p.x = this.width / 2 + Math.cos(angle) * this.width * distance;
      p.y = this.height / 2 + Math.sin(angle) * this.height * distance;
      p.vx = Math.cos(angle) * 4; p.vy = Math.sin(angle) * 4;
    }
  }

  advance(seconds: number, words: BloomPoint[], pointer: BloomPoint | null) {
    if (this.options.speed === 0 || !Number.isFinite(seconds) || seconds <= 0) return 0;
    this.accumulator += Math.min(seconds * this.options.speed, 1 / 15);
    let steps = 0;
    while (this.accumulator + 1e-10 >= 1 / 60 && steps < 4) {
      this.step(words, pointer);
      this.accumulator = Math.max(0, this.accumulator - 1 / 60);
      steps++;
    }
    return steps;
  }

  private step(words: BloomPoint[], pointer: BloomPoint | null) {
    const o = this.options;
    for (const p of this.particles) {
      p.angle += (this.random() - 0.5) * 0.2;
      p.vx = (p.vx + Math.cos(p.angle) * o.wander) * o.damping;
      p.vy = (p.vy + Math.sin(p.angle) * o.wander) * o.damping;
      if (pointer && Math.hypot(pointer.x - p.x, pointer.y - p.y) < o.pointerRadius) {
        p.vx += (pointer.x - p.x) * 0.002 * o.pointerAttraction;
        p.vy += (pointer.y - p.y) * 0.002 * o.pointerAttraction;
      }
      let nearest: BloomPoint | undefined;
      let distance = Infinity;
      for (const word of words) {
        const d = Math.hypot(word.x - p.x, word.y - p.y);
        if (d < distance) { distance = d; nearest = word; }
      }
      if (this.gathering && !nearest) nearest = { x: this.width / 2, y: this.height / 2 };
      if (nearest && (distance < o.textRadius || this.gathering > 0)) {
        const force = this.gathering ? 0.01 : 0.01 * o.textAttraction;
        p.vx += (nearest.x - p.x) * force;
        p.vy += (nearest.y - p.y) * force;
      }
      p.x += p.vx; p.y += p.vy;
      if (p.x < 0) p.x = this.width;
      if (p.x > this.width) p.x = 0;
      if (p.y < 0) p.y = this.height;
      if (p.y > this.height) p.y = 0;
    }
    this.gathering = Math.max(0, this.gathering - 1);
  }
}

export type ChartColor = "pink" | "blue" | "olive" | "yellow" | "ink";
export type ChartSeries = { key: string; label: string; color?: ChartColor };
export type ChartPoint = {
  label: string;
  [key: string]: string | number | null | undefined;
};
export type ChartSlice = {
  label: string;
  value: number | null;
  color?: ChartColor;
};
export type PlotPoint = { x: number; y: number };
export type Curve = "linear" | "smooth" | "step";
export const chartColors: ChartColor[] = [
  "pink",
  "blue",
  "olive",
  "yellow",
  "ink",
];
export const chartColor = (color: ChartColor | undefined, index = 0) =>
  `var(--v-${color ?? chartColors[index % chartColors.length]})`;
export const finiteValue = (value: unknown): number | null =>
  typeof value === "number" && Number.isFinite(value) ? value : null;
export const clamp = (value: number, low: number, high: number) =>
  Math.max(low, Math.min(high, Number.isFinite(value) ? value : low));
const n = (value: number) =>
  Number((Number.isFinite(value) ? value : 0).toFixed(3));

/** Missing/non-finite observations stay missing; they never become zero in the table. */
export function cleanChartData(data: ChartPoint[], series: ChartSeries[]) {
  return data.map((point) => ({
    label: String(point.label),
    values: series.map((item) => finiteValue(point[item.key])),
  }));
}
export function chartDomain(
  data: ChartPoint[],
  series: ChartSeries[],
  stacked = false,
): [number, number] {
  let low = 0,
    high = 0;
  for (const point of cleanChartData(data, series)) {
    if (stacked) {
      low = Math.min(
        low,
        point.values.reduce<number>(
          (sum, value) => sum + Math.min(0, value ?? 0),
          0,
        ),
      );
      high = Math.max(
        high,
        point.values.reduce<number>(
          (sum, value) => sum + Math.max(0, value ?? 0),
          0,
        ),
      );
    } else
      for (const value of point.values) {
        low = Math.min(low, value ?? 0);
        high = Math.max(high, value ?? 0);
      }
  }
  // A zero-only set still has a stable, finite axis and inspectable observations.
  if (low === high) return [0, 1];
  const padding = (high - low) * 0.08;
  return [low < 0 ? low - padding : 0, high > 0 ? high + padding : 0];
}
export function scaleValue(
  value: number,
  domain: [number, number],
  start: number,
  end: number,
) {
  const span = domain[1] - domain[0];
  return span > 0 && Number.isFinite(span)
    ? start + ((value - domain[0]) / span) * (end - start)
    : start;
}
export function stackChartData(data: ChartPoint[], series: ChartSeries[]) {
  return cleanChartData(data, series).map((point) => {
    let positive = 0,
      negative = 0;
    return point.values.map((value) => {
      if (value === null) return null;
      const start = value >= 0 ? positive : negative;
      const end = start + value;
      if (value >= 0) positive = end;
      else negative = end;
      return { start, end, value };
    });
  });
}
export function linePath(
  points: (PlotPoint | null)[],
  curve: Curve = "linear",
) {
  let previous: PlotPoint | null = null,
    path = "";
  for (const point of points) {
    if (!point) {
      previous = null;
      continue;
    }
    if (!previous) path += `M${n(point.x)},${n(point.y)}`;
    else if (curve === "step") path += `H${n(point.x)}V${n(point.y)}`;
    else if (curve === "smooth") {
      const mid = (previous.x + point.x) / 2;
      path += `C${n(mid)},${n(previous.y)} ${n(mid)},${n(point.y)} ${n(point.x)},${n(point.y)}`;
    } else path += `L${n(point.x)},${n(point.y)}`;
    previous = point;
  }
  return path;
}
export function areaPath(
  top: (PlotPoint | null)[],
  bottom: (PlotPoint | null)[],
  curve: Curve = "linear",
) {
  let path = "",
    start = 0;
  while (start < top.length) {
    while (start < top.length && (!top[start] || !bottom[start])) start++;
    let end = start;
    while (end < top.length && top[end] && bottom[end]) end++;
    if (end > start)
      path +=
        linePath(top.slice(start, end), curve) +
        linePath(bottom.slice(start, end).reverse(), curve).replace(/^M/, "L") +
        "Z";
    start = end + 1;
  }
  return path;
}
export function polarPoint(
  cx: number,
  cy: number,
  radius: number,
  angle: number,
): PlotPoint {
  return { x: cx + Math.cos(angle) * radius, y: cy + Math.sin(angle) * radius };
}
/** Two arcs also make exact full circles well-defined in SVG. */
export function arcPath(
  cx: number,
  cy: number,
  outer: number,
  inner: number,
  start: number,
  end: number,
) {
  const sweep = clamp(end - start, 0, Math.PI * 2);
  if (sweep <= 0 || outer <= 0) return "";
  const mid = start + sweep / 2,
    finish = start + sweep;
  const a = polarPoint(cx, cy, outer, start),
    b = polarPoint(cx, cy, outer, mid),
    c = polarPoint(cx, cy, outer, finish);
  const outerPath = `M${n(a.x)},${n(a.y)}A${n(outer)},${n(outer)} 0 0 1 ${n(b.x)},${n(b.y)}A${n(outer)},${n(outer)} 0 0 1 ${n(c.x)},${n(c.y)}`;
  if (inner <= 0) return `${outerPath}L${n(cx)},${n(cy)}Z`;
  const d = polarPoint(cx, cy, inner, finish),
    e = polarPoint(cx, cy, inner, mid),
    f = polarPoint(cx, cy, inner, start);
  return `${outerPath}L${n(d.x)},${n(d.y)}A${n(inner)},${n(inner)} 0 0 0 ${n(e.x)},${n(e.y)}A${n(inner)},${n(inner)} 0 0 0 ${n(f.x)},${n(f.y)}Z`;
}
export function pieAngles(data: ChartSlice[]) {
  const values = data.map((item) => Math.max(0, finiteValue(item.value) ?? 0));
  const total = values.reduce((sum, value) => sum + value, 0);
  let angle = -Math.PI / 2;
  return values.map((value, index) => {
    const start = angle;
    angle += total > 0 ? (value / total) * Math.PI * 2 : 0;
    return { index, value, start, end: angle, total };
  });
}
export function radarPath(points: (PlotPoint | null)[], rounded = false) {
  if (!points.length) return "";
  const missing = points.indexOf(null);
  // Begin just after a missing axis so a valid run can cross the final/first axis.
  // Open runs have no fill and never imply an observation at the origin.
  if (missing !== -1)
    return linePath([
      ...points.slice(missing + 1),
      ...points.slice(0, missing + 1),
    ]);
  const observed = points.filter((point): point is PlotPoint => point !== null);
  if (!rounded) return linePath([...observed, observed[0]]) + "Z";
  const middle = (a: PlotPoint, b: PlotPoint) => ({
    x: (a.x + b.x) / 2,
    y: (a.y + b.y) / 2,
  });
  const start = middle(observed.at(-1)!, observed[0]);
  let result = `M${n(start.x)},${n(start.y)}`;
  observed.forEach((point, index) => {
    const end = middle(point, observed[(index + 1) % observed.length]);
    result += `Q${n(point.x)},${n(point.y)} ${n(end.x)},${n(end.y)}`;
  });
  return result + "Z";
}
export function tooltipPosition(
  x: number,
  y: number,
  width: number,
  height: number,
  tipWidth: number,
  tipHeight: number,
) {
  const left = x + 16 + tipWidth <= width - 8 ? x + 16 : x - tipWidth - 16;
  const top = y + 12 + tipHeight <= height - 8 ? y + 12 : y - tipHeight - 12;
  return {
    x: clamp(left, 8, Math.max(8, width - tipWidth - 8)),
    y: clamp(top, 8, Math.max(8, height - tipHeight - 8)),
  };
}

import type { CSSProperties } from "react";

export type ControlRadius = "square" | "soft" | "round" | "pill";
export type FieldAppearance = "contour" | "editorial" | "inset";
export type ControlAppearanceProps = { radius?: ControlRadius; appearance?: FieldAppearance };

/** Omission inherits the nearest owner's corners; no preference state is created. */
export function controlRadiusStyle(radius?: ControlRadius): CSSProperties | undefined {
  if (!radius) return undefined;
  return { "--v-control-radius": { square: "0px", soft: "8px", round: "20px", pill: "999px" }[radius] } as CSSProperties;
}

import { rasterizeSculpture } from "@/lib/cojeev/sculpture-raster";
/** Original organic geometry and a small, dependency-free character-cell rasterizer. */
export type GlyphForm = "seed" | "bloom" | "pebble";
export type GlyphTone = "ink" | "rose" | "moss" | "sky";
export const GLYPH_RAMP = " .,:;=+*#%@";
type Vector = [number, number, number];
export type GlyphMesh = { positions: Float32Array; normals: Float32Array; triangles: Uint16Array };
export type GlyphGrid = { columns: number; rows: number; cellWidth: number; cellHeight: number; width: number; height: number };
const bounded = (value: number | undefined, fallback: number, min: number, max: number) => Number.isFinite(value) ? Math.max(min, Math.min(max, value!)) : fallback;

export function normalizeGlyphOptions({ speed, cellSize, turn }: { speed?: number; cellSize?: number; turn?: number } = {}) {
  return { speed: bounded(speed, 1, 0, 3), cellSize: bounded(cellSize, 10, 7, 20), turn: bounded(turn, 0, -180, 180) };
}

export function glyphGrid(width: number, height: number, cellSize: number): GlyphGrid {
  width = bounded(width, 1, 1, 20000); height = bounded(height, 1, 1, 20000);
  const size = Math.max(bounded(cellSize, 10, 7, 20), width / (140 * .62), height / 90);
  const columns = Math.max(1, Math.min(140, Math.floor(width / (size * .62))));
  const rows = Math.max(1, Math.min(90, Math.floor(height / size)));
  return { columns, rows, cellWidth: width / columns, cellHeight: height / rows, width, height };
}

function surface(form: GlyphForm, longitude: number, latitude: number): Vector {
  const ring = Math.sin(latitude), height = Math.cos(latitude);
  const x = Math.cos(longitude), z = Math.sin(longitude);
  if (form === "seed") return [.69 * ring * x * (1 + .2 * height), 1.08 * height, .5 * ring * z * (1 - .18 * height)];
  if (form === "bloom") {
    // A soft five-lobed cushion, with a shallow dimple at the center of each face.
    const radius = .83 + .19 * Math.cos(5 * longitude);
    return [radius * ring * x, radius * ring * z, .44 * height * (1 - .28 * Math.exp(-ring * ring * 12))];
  }
  const radius = 1 + .09 * Math.cos(3 * longitude + .3) * ring;
  return [.94 * ring * x * radius, .79 * height + .05 * ring * Math.sin(2 * longitude), .66 * ring * z * radius];
}

function unit(x: number, y: number, z: number): Vector {
  const length = Math.hypot(x, y, z) || 1;
  return [x / length, y / length, z / length];
}

export function createGlyphMesh(form: GlyphForm): GlyphMesh {
  const around = 64, vertical = 32;
  const positions = new Float32Array((around + 1) * (vertical + 1) * 3);
  const normals = new Float32Array(positions.length);
  const triangles: number[] = [];
  for (let row = 0; row <= vertical; row++) for (let column = 0; column <= around; column++) {
    const longitude = column / around * Math.PI * 2, latitude = row / vertical * Math.PI;
    const index = (row * (around + 1) + column) * 3;
    const point = surface(form, longitude, latitude);
    positions.set(point, index);
    const u0 = surface(form, longitude - .001, latitude), u1 = surface(form, longitude + .001, latitude);
    const v0 = surface(form, longitude, latitude - .001), v1 = surface(form, longitude, latitude + .001);
    const u = u1.map((value, i) => value - u0[i]), v = v1.map((value, i) => value - v0[i]);
    let normal = unit(u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]);
    if (row === 0 || row === vertical) normal = unit(...point);
    if (normal.reduce((sum, value, i) => sum + value * point[i], 0) < 0) normal = normal.map(value => -value) as Vector;
    normals.set(normal, index);
    if (row < vertical && column < around) {
      const a = row * (around + 1) + column, b = a + around + 1;
      triangles.push(a, b, a + 1, a + 1, b, b + 1);
    }
  }
  return { positions, normals, triangles: new Uint16Array(triangles) };
}

/** Compatibility density-grid API backed by the shared depth-tested surface. */
export function rasterizeGlyphs(mesh: GlyphMesh, grid: GlyphGrid, yaw = .35, pitch = -.2): Uint8Array {
  const frame = rasterizeSculpture(mesh, grid, yaw, pitch), cells = new Uint8Array(frame.coverage.length);
  for (let i = 0; i < cells.length; i++) if (frame.coverage[i]) cells[i] = Math.max(1, Math.min(GLYPH_RAMP.length - 1, Math.round(frame.light[i] * (GLYPH_RAMP.length - 2)) + 1));
  return cells;
}

export function glyphText(cells: Uint8Array, columns: number): string {
  const lines: string[] = [];
  for (let i = 0; i < cells.length; i += columns) lines.push(Array.from(cells.subarray(i, i + columns), value => GLYPH_RAMP[value]).join(""));
  return lines.join("\n");
}

"use client";

import * as React from "react";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";

export type FieldTone = "balanced" | "warm" | "cool";
export type LivingShaderKind = "pigment" | "contour";
export type LivingShaderStatus = "pending" | "webgl" | "fallback" | "lost";
export type FieldMotionProps = {
  /** Relative pace, from 0 (still) to 3. */
  speed?: number;
  /** Color and relief strength, from 0 to 2. */
  intensity?: number;
  /** Accent selection from the inherited Cojeev theme. */
  tone?: FieldTone;
  /** Freeze the current artwork without removing it. */
  paused?: boolean;
};

function finite(value: number | undefined, fallback: number, min: number, max: number) {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

export function normalizeShaderMotion(speed?: number, intensity?: number) {
  return { speed: finite(speed, 1, 0, 3), intensity: finite(intensity, 1, 0, 2) };
}

/** A large retina hero must not allocate an unbounded drawing buffer. */
export function shaderResolution(cssWidth: number, cssHeight: number, deviceRatio: number) {
  if (cssWidth <= 0 || cssHeight <= 0) return { width: 1, height: 1 };
  const width = finite(cssWidth, 1, 1, 1e7);
  const height = finite(cssHeight, 1, 1, 1e7);
  const ratio = finite(deviceRatio, 1, 1, 2);
  const scale = Math.min(ratio, 4096 / width, 4096 / height, Math.sqrt(2_000_000 / (width * height)));
  return { width: Math.max(1, Math.floor(width * scale)), height: Math.max(1, Math.floor(height * scale)) };
}

const vertexSource = `
attribute vec2 aPosition;
void main() { gl_Position = vec4(aPosition, 0.0, 1.0); }
`;

// Original Cojeev field functions: analytic color densities and topographic bands.
// No framebuffer simulation, DOM capture, texture assets, or third-party shader code.
const fragmentSource = `
precision mediump float;
uniform vec2 uSize;
uniform float uTime;
uniform float uIntensity;
uniform float uKind;
uniform vec3 uPaper;
uniform vec3 uA;
uniform vec3 uB;
uniform vec3 uC;

float mound(vec2 p, vec2 center, vec2 stretch) {
  vec2 d = (p - center) * stretch;
  return exp(-dot(d, d));
}

void main() {
  vec2 uv = gl_FragCoord.xy / uSize;
  float aspect = uSize.x / max(uSize.y, 1.0);
  vec2 p = vec2((uv.x - 0.5) * min(aspect, 2.5), uv.y - 0.5);
  float t = uTime * 0.16;
  vec2 drift = vec2(sin(t * 0.71), cos(t * 0.53)) * 0.12;
  vec2 folded = p + vec2(sin(p.y * 5.7 + t), cos(p.x * 4.1 - t * 0.8)) * 0.09;
  float a = mound(folded, vec2(-0.43, 0.16) + drift, vec2(1.8, 2.8));
  float b = mound(folded, vec2(0.40, -0.23) - drift * 0.8, vec2(2.1, 2.3));
  float c = mound(folded, vec2(0.05, 0.38) + drift.yx * 0.6, vec2(2.9, 1.9));
  vec3 color = uPaper;
  if (uKind < 0.5) {
    float wash = sin(folded.x * 10.0 + folded.y * 7.0 + t * 0.7) * 0.08;
    color = mix(color, uA, smoothstep(0.07, 0.94, a + wash) * 0.70);
    color = mix(color, uB, smoothstep(0.05, 0.90, b - wash) * 0.65);
    color = mix(color, uC, smoothstep(0.08, 0.94, c) * 0.40);
    float edge = exp(-abs(a - 0.42) * 35.0) * 0.035;
    color = mix(color, uA, edge);
  } else {
    float height = a * 1.25 + b * 0.92 + c * 0.55;
    height += sin(folded.x * 4.5 - folded.y * 3.0 + t * 0.3) * 0.13;
    float phase = height * 13.0;
    float distanceToLine = abs(fract(phase) - 0.5);
    float line = 1.0 - smoothstep(0.018, 0.07, distanceToLine);
    float broadLine = 1.0 - smoothstep(0.10, 0.18, distanceToLine);
    vec3 terrain = mix(uA, uB, smoothstep(0.2, 1.5, height));
    color = mix(uPaper, terrain, 0.10 + height * 0.07);
    color = mix(color, terrain, broadLine * 0.16 + line * 0.38);
    color = mix(color, uC, line * smoothstep(0.8, 1.8, height) * 0.24);
  }
  float fiber = sin(gl_FragCoord.x * 1.37 + gl_FragCoord.y * 2.17) * 0.003;
  color = mix(uPaper, color, min(uIntensity, 1.0));
  color = mix(color, color * 0.94, max(uIntensity - 1.0, 0.0));
  gl_FragColor = vec4(clamp(color + fiber * min(uIntensity, 1.0), 0.0, 1.0), 1.0);
}
`;

type ShaderOptions = ReturnType<typeof normalizeShaderMotion> & { tone: FieldTone; visible: boolean; moving: boolean };
export type LivingShader = { update: (options: ShaderOptions) => void; dispose: () => void };

/** Owns one GPU program and its complete context, resize, theme and frame lifecycle. */
export function createLivingShader(
  canvas: HTMLCanvasElement,
  host: HTMLElement,
  kind: LivingShaderKind,
  onStatus: (status: LivingShaderStatus) => void,
): LivingShader {
  let gl: WebGLRenderingContext | null = null;
  let program: WebGLProgram | null = null;
  let buffer: WebGLBuffer | null = null;
  const shaders: WebGLShader[] = [];
  let locations: Record<string, WebGLUniformLocation | null> = {};
  let disposed = false, lost = false, failed = false, frame = 0, previous = 0, elapsed = 0;
  let options: ShaderOptions = { speed: 1, intensity: 1, tone: "balanced", visible: false, moving: false };
  let themeDirty = true, sizeDirty = true, announced = false;
  const colors = document.createElement("canvas");
  colors.width = colors.height = 1;
  const colorContext = colors.getContext("2d", { willReadFrequently: true });

  function cancel() {
    if (frame) cancelAnimationFrame(frame);
    frame = 0;
    previous = 0;
  }
  function release() {
    if (gl && !lost) {
      if (buffer) gl.deleteBuffer(buffer);
      if (program) gl.deleteProgram(program);
      for (const shader of shaders) gl.deleteShader(shader);
    }
    buffer = null; program = null; shaders.length = 0; locations = {};
  }
  function unavailable() {
    cancel(); release(); failed = true; onStatus("fallback");
  }
  function compile(type: number, source: string) {
    const shader = gl!.createShader(type);
    if (!shader) throw new Error("Shader allocation failed");
    shaders.push(shader);
    gl!.shaderSource(shader, source); gl!.compileShader(shader);
    if (!gl!.getShaderParameter(shader, gl!.COMPILE_STATUS)) throw new Error("Shader compilation failed");
    return shader;
  }
  function initialize() {
    if (disposed || lost || failed || program) return;
    try {
      gl = canvas.getContext("webgl", { alpha: false, antialias: false, depth: false, stencil: false, powerPreference: "low-power" });
      if (!gl || gl.isContextLost()) throw new Error("WebGL unavailable");
      program = gl.createProgram();
      if (!program) throw new Error("Program allocation failed");
      gl.attachShader(program, compile(gl.VERTEX_SHADER, vertexSource));
      gl.attachShader(program, compile(gl.FRAGMENT_SHADER, fragmentSource));
      gl.linkProgram(program);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error("Program link failed");
      buffer = gl.createBuffer();
      if (!buffer) throw new Error("Buffer allocation failed");
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
      gl.useProgram(program);
      const position = gl.getAttribLocation(program, "aPosition");
      gl.enableVertexAttribArray(position);
      gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
      for (const name of ["uSize", "uTime", "uIntensity", "uKind", "uPaper", "uA", "uB", "uC"]) locations[name] = gl.getUniformLocation(program, name);
      themeDirty = sizeDirty = true;
      announced = false;
    } catch { unavailable(); }
  }
  function color(value: string, fallback: string) {
    if (!colorContext) return [0.8, 0.8, 0.8];
    colorContext.clearRect(0, 0, 1, 1);
    colorContext.fillStyle = fallback;
    colorContext.fillStyle = value || fallback;
    colorContext.fillRect(0, 0, 1, 1);
    const pixel = colorContext.getImageData(0, 0, 1, 1).data;
    return [pixel[0] / 255, pixel[1] / 255, pixel[2] / 255];
  }
  function repaintTheme() {
    const css = getComputedStyle(host);
    const accents = options.tone === "warm" ? ["pink", "yellow", "olive"] : options.tone === "cool" ? ["blue", "olive", "pink"] : ["pink", "blue", "yellow"];
    const tokens = ["--v-paper", ...accents.map(name => `--v-${name}`)];
    const defaults = ["#fbf4e6", "#f5b8db", "#b6caeb", "#f5d867"];
    ["uPaper", "uA", "uB", "uC"].forEach((name, index) => gl!.uniform3fv(locations[name], color(css.getPropertyValue(tokens[index]).trim(), defaults[index])));
    themeDirty = false;
  }
  function canDraw() { return !disposed && !lost && !failed && options.visible && !document.hidden; }
  function request() { if (canDraw() && !frame) frame = requestAnimationFrame(draw); }
  function draw(time: number) {
    frame = 0;
    if (!canDraw()) { previous = 0; return; }
    initialize();
    if (!gl || !program || failed) return;
    try {
      if (sizeDirty) {
        const { width, height } = shaderResolution(host.clientWidth, host.clientHeight, window.devicePixelRatio);
        if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
        gl.viewport(0, 0, width, height);
        gl.uniform2f(locations.uSize, width, height);
        sizeDirty = false;
      }
      if (themeDirty) repaintTheme();
      const delta = previous ? Math.min(Math.max(0, (time - previous) / 1000), 0.05) : 0;
      if (options.moving) elapsed += delta * options.speed;
      previous = time;
      gl.uniform1f(locations.uTime, elapsed);
      gl.uniform1f(locations.uIntensity, options.intensity);
      gl.uniform1f(locations.uKind, kind === "pigment" ? 0 : 1);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      if (!announced) { announced = true; onStatus("webgl"); }
      if (options.moving && options.speed > 0 && options.intensity > 0) request();
      else previous = 0;
    } catch { unavailable(); }
  }
  function resize() { sizeDirty = true; request(); }
  function appearance() { themeDirty = true; request(); }
  function visibility() { cancel(); if (!document.hidden) request(); }
  function onLost(event: Event) {
    event.preventDefault(); lost = true; cancel(); release(); onStatus("lost");
  }
  function onRestored() {
    if (disposed) return;
    lost = false; failed = false; gl = null; themeDirty = sizeDirty = true; request();
  }
  canvas.addEventListener("webglcontextlost", onLost);
  canvas.addEventListener("webglcontextrestored", onRestored);
  document.addEventListener("visibilitychange", visibility);
  window.addEventListener("resize", resize, { passive: true });
  window.addEventListener("cojeev:appearancechange", appearance);
  const resizeObserver = new ResizeObserver(resize); resizeObserver.observe(host);
  // Theme scopes can be nested; observe the actual ancestry, not only :root.
  const themeObserver = new MutationObserver(appearance);
  let ancestor: HTMLElement | null = host;
  while (ancestor) { themeObserver.observe(ancestor, { attributes: true, attributeFilter: ["style", "class", "data-mode", "data-theme"] }); ancestor = ancestor.parentElement; }

  return {
    update(next) {
      if (disposed) return;
      const motion = normalizeShaderMotion(next.speed, next.intensity);
      themeDirty ||= options.tone !== next.tone;
      const changed = options.speed !== motion.speed || options.intensity !== motion.intensity || options.tone !== next.tone || options.visible !== next.visible || options.moving !== next.moving;
      options = { ...next, ...motion };
      if (!options.visible || !options.moving) cancel();
      if (changed || themeDirty || sizeDirty) request();
    },
    dispose() {
      if (disposed) return;
      disposed = true; cancel();
      canvas.removeEventListener("webglcontextlost", onLost);
      canvas.removeEventListener("webglcontextrestored", onRestored);
      document.removeEventListener("visibilitychange", visibility);
      window.removeEventListener("resize", resize);
      window.removeEventListener("cojeev:appearancechange", appearance);
      resizeObserver.disconnect(); themeObserver.disconnect(); release();
      // Releasing GPU objects is enough; forcing loss breaks React Strict Mode's
      // immediate remount on the same canvas. The browser retires detached contexts.
      gl = null;
    },
  };
}

export function useLivingShader(kind: LivingShaderKind, props: FieldMotionProps) {
  const host = React.useRef<HTMLDivElement>(null);
  const canvas = React.useRef<HTMLCanvasElement>(null);
  const renderer = React.useRef<LivingShader | null>(null);
  const [status, setStatus] = React.useState<LivingShaderStatus>("pending");
  const { enabled, inView } = useMotionVisibility(host);
  const { speed, intensity } = normalizeShaderMotion(props.speed, props.intensity);
  const tone = props.tone === "cool" || props.tone === "warm" ? props.tone : "balanced";
  const moving = enabled && !props.paused && speed > 0 && intensity > 0;

  React.useEffect(() => {
    if (!canvas.current || !host.current) return;
    renderer.current = createLivingShader(canvas.current, host.current, kind, next => setStatus(previous => previous === next ? previous : next));
    return () => { renderer.current?.dispose(); renderer.current = null; };
  }, [kind]);
  React.useEffect(() => { renderer.current?.update({ speed, intensity, tone, visible: inView, moving }); }, [speed, intensity, tone, inView, moving]);
  return { host, canvas, status, tone, intensity, moving: status === "webgl" && moving && inView };
}

export type MarqueeMotion = { phase: number; velocity: number; scrollVelocity: number; scrollDirection: number };

export function marqueeScrollVelocity(distance: number, seconds: number) {
  if (!Number.isFinite(distance + seconds) || seconds <= 0) return 0;
  return Math.max(-2400, Math.min(2400, distance / Math.max(.016, seconds)));
}

/** Bounded integration keeps reversal continuous and background-tab time from accumulating. */
export function advanceMarquee(state: MarqueeMotion, seconds: number, pace: number, period: number, followScroll: boolean): MarqueeMotion {
  if (![seconds, pace, period, state.phase, state.velocity, state.scrollVelocity].every(Number.isFinite) || period <= 0) return { phase: 0, velocity: 0, scrollVelocity: 0, scrollDirection: 1 };
  const dt = Math.max(0, Math.min(.05, seconds));
  const scrollVelocity = followScroll ? state.scrollVelocity * Math.exp(-dt * 5) : 0;
  const scrollDirection = followScroll && Math.abs(scrollVelocity) > 30 ? Math.sign(scrollVelocity) : followScroll ? state.scrollDirection : 1;
  const target = Math.max(-160, Math.min(160, pace)) * scrollDirection * (1 + Math.min(2.2, Math.abs(scrollVelocity) / 800));
  const velocity = state.velocity + (target - state.velocity) * (1 - Math.exp(-dt * 6));
  const phase = ((state.phase + velocity * dt) % period + period) % period;
  return { phase, velocity, scrollVelocity, scrollDirection };
}

export function marqueeDepth(midpoint: number, viewport: number, amount: number) {
  const depth = Number.isFinite(amount) ? Math.max(0, Math.min(1, amount)) : .65;
  const distance = Math.min(1, Math.abs(midpoint - viewport / 2) / Math.max(1, viewport / 2));
  return { blur: distance * distance * depth * 3, opacity: 1 - distance * depth * .28 };
}

export type NumberPart = { key: string; text: string; digit?: number; glyphs?: string[] };

/** Keep Intl's punctuation and bidi literals intact; only decimal digits become wheels. */
export function numberParts(formatter: Intl.NumberFormat, value: number): NumberPart[] {
  const resolved = formatter.resolvedOptions();
  const digits = new Intl.NumberFormat(resolved.locale, { useGrouping: false, numberingSystem: resolved.numberingSystem });
  const glyphs = Array.from({ length: 10 }, (_, digit) => digits.format(digit));
  const parts = formatter.formatToParts(value);
  const integerLength = parts.filter(part => part.type === "integer").reduce((length, part) => length + Array.from(part.value).length, 0);
  let integer = integerLength, fraction = 0;
  const occurrences: Record<string, number> = {};
  return parts.flatMap(part => {
    if (part.type === "integer" || part.type === "fraction") return Array.from(part.value).map(text => {
      const digit = glyphs.indexOf(text);
      const key = part.type === "integer" ? `integer:${--integer}` : `fraction:${fraction++}`;
      return { key, text, ...(digit < 0 ? {} : { digit, glyphs }) };
    });
    const occurrence = occurrences[part.type] ?? 0;
    occurrences[part.type] = occurrence + 1;
    return [{ key: `${part.type}:${occurrence}`, text: part.value }];
  });
}

/** Choose the next matching digit without resetting an interrupted fractional position. */
export function rollingTarget(current: number, digit: number, direction: number) {
  const cycle = Math.floor(current / 10) * 10;
  let target = cycle + digit;
  if (direction >= 0 && target < current - 1e-7) target += 10;
  if (direction < 0 && target > current + 1e-7) target -= 10;
  return target;
}

export function mixNumber(from: number, to: number, progress: number) {
  if (progress >= 1) return to;
  if (progress <= 0) return from;
  return Math.sign(from) === Math.sign(to) ? from + (to - from) * progress : from * (1 - progress) + to * progress;
}

/** Base-aware decimal stepping, with a bounded precision that avoids visible floating point tails. */
export function stepNumber(value: number | null, direction: 1 | -1, step = 1, min?: number, max?: number) {
  const amount = Number.isFinite(step) && step > 0 ? step : 1;
  const lower = Number.isFinite(min) ? min! : -Infinity;
  const upper = Number.isFinite(max) ? Math.max(lower, max!) : Infinity;
  const base = Number.isFinite(lower) ? lower : 0;
  if (value === null || !Number.isFinite(value)) return Math.min(upper, Math.max(lower, Number.isFinite(lower) ? lower : Number.isFinite(upper) && upper < 0 ? upper : 0));
  const position = (value - base) / amount;
  const nearest = Math.round(position);
  const aligned = Math.abs(position - nearest) < 1e-9;
  const next = aligned ? nearest + direction : direction > 0 ? Math.ceil(position) : Math.floor(position);
  const result = base + next * amount;
  const decimals = (number: number) => { const [mantissa, exponent = "0"] = String(number).split("e"); return Math.max(0, (mantissa.split(".")[1]?.length ?? 0) - Number(exponent)); };
  const precision = Math.max(decimals(base), decimals(amount));
  // Preserve all integer digits; only remove fractional arithmetic tails at the step's precision.
  const clean = Number.isFinite(result) ? Number(precision <= 100 ? result.toFixed(precision) : result.toPrecision(15)) : value;
  return Math.min(upper, Math.max(lower, clean));
}

/** Parse editable decimal text in the chosen numbering system; punctuation remains data until commit. */
export function parseNumberInput(text: string, locale = "en-US"): number | null | undefined {
  if (!text.trim()) return null;
  const formatter = new Intl.NumberFormat(locale);
  const parts = formatter.formatToParts(-12345.6);
  const decimal = parts.find(part => part.type === "decimal")?.value ?? ".";
  const group = parts.find(part => part.type === "group")?.value;
  const minus = parts.find(part => part.type === "minusSign")?.value ?? "-";
  let normalized = text.trim().replace(/[\u061c\u200e\u200f]/g, "");
  if (group) normalized = normalized.split(group).join("");
  normalized = normalized.split(decimal).join(".").split(minus).join("-");
  const digits = new Intl.NumberFormat(locale, { useGrouping: false });
  for (let digit = 0; digit < 10; digit++) normalized = normalized.split(digits.format(digit)).join(String(digit));
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(normalized)) return undefined;
  const value = Number(normalized);
  return Number.isFinite(value) ? value : undefined;
}

/** Editable text preserves the number's full significant precision, including scientific notation. */
export function numberInputText(value: number, locale = "en-US") {
  const formatter = new Intl.NumberFormat(locale, { useGrouping: false });
  const parts = formatter.formatToParts(-1.5);
  const decimal = parts.find(part => part.type === "decimal")?.value ?? ".";
  const minus = parts.find(part => part.type === "minusSign")?.value ?? "-";
  return (Object.is(value, -0) ? "-0" : String(value)).replace(/[0-9.-]/g, character => character === "." ? decimal : character === "-" ? minus : formatter.format(Number(character)));
}

export type GuidedPointerPoint = {
  id: string;
  /** Normalized position within the available stage area, from zero to one. */
  x: number;
  y: number;
  click?: boolean;
  pressed?: boolean;
};

/** Keep the first valid occurrence of each ID without mutating caller data. */
export function normalizePointerPoints(points: readonly GuidedPointerPoint[]): GuidedPointerPoint[] {
  const seen = new Set<string>();
  return points.flatMap(point => {
    if (!point.id.trim() || seen.has(point.id) || !Number.isFinite(point.x) || !Number.isFinite(point.y)) return [];
    seen.add(point.id);
    return [{ ...point, x: Math.min(1, Math.max(0, point.x)), y: Math.min(1, Math.max(0, point.y)) }];
  });
}

/** Omitted selection uses the first valid point; an unknown selection stays empty. */
export function resolvePointerPoint(points: readonly GuidedPointerPoint[], activeId?: string) {
  const normalized = normalizePointerPoints(points);
  return activeId === undefined ? normalized[0] : normalized.find(point => point.id === activeId);
}

const finite=(value:number,min:number,max:number,fallback:number)=>Number.isFinite(value)?Math.max(min,Math.min(max,value)):fallback;
const segment=(text:string)=>Array.from(new Intl.Segmenter(undefined,{granularity:"grapheme"}).segment(text),item=>item.segment);
const pool="#%&@/+<>*=~ABCDEFGHKMNPRSTUVWXYZ0123456789";
export type HeadingDecodeOptions={scrambleLength:number;preserveChance:number;tailChance:number};
export function decodeHeading(text:string,progress:number,frame:number,options:HeadingDecodeOptions):string[]{
 const chars=segment(text),p=finite(progress,0,1,1);
 if(p>=1)return chars;
 const boundary=Math.floor((1-(1-p)**2)*chars.length),noise=Math.round(finite(options.scrambleLength,0,30,10));
 return chars.map((char,index)=>{
  if(index<boundary||/\s/u.test(char))return char;
  const sample=((index+1)*73+Math.floor(frame)*37+index*index*11)%997/997;
  const preserve=index<boundary+noise?finite(options.preserveChance,0,1,.25):1-finite(options.tailChance,0,1,.12);
  return sample<preserve?char:pool[(index*17+Math.floor(frame)*7)%pool.length];
 });
}
export function headingTiming(duration:number,stagger:number,count:number){return{duration:finite(duration,100,3000,700),delay:Math.min(finite(stagger,0,600,140),1200/Math.max(1,count-1))};}
export function normalizePortal(speed:number,intensity:number,distortion:number){return{speed:finite(speed,0,3,.7),intensity:finite(intensity,0,2,1),distortion:finite(distortion,0,1.5,.7)};}
/** Fixed precision makes the semantic server fallback identical across JS engines. */
export function portalContour(time:number,distortion:number,offset=0){
 const d=finite(distortion,0,1.5,.7),t=finite(time,0,1e9,0),points:string[]=[];
 for(let i=0;i<96;i++){const a=i/96*Math.PI*2,r=126+offset+(Math.sin(a*3+t*.4)*13+Math.cos(a*5-t*.3)*7)*d;points.push(`${(320+Math.cos(a)*r*1.3).toFixed(3)} ${(220+Math.sin(a)*r).toFixed(3)}`);}
 return "M"+points.join("L")+"Z";
}

import { shaderResolution } from "@/lib/cojeev/living-shader";
import { normalizePortal } from "@/lib/cojeev/reference-additions-math";
export type PortalOptions={speed:number;intensity:number;distortion:number;tone:"balanced"|"warm"|"cool";visible:boolean;moving:boolean};
export type PortalStatus="pending"|"webgl"|"fallback"|"lost";
const vertex=`attribute vec2 aPosition;void main(){gl_Position=vec4(aPosition,0.,1.);}`;
/** Original organic annular distance field: domain warp, luminous core, broad chromatic fringe. */
const fragment=`precision mediump float;
uniform vec2 uSize;uniform vec2 uPointer;uniform float uTime;uniform float uIntensity;uniform float uDistortion;
uniform vec3 uPaper;uniform vec3 uCore;uniform vec3 uFringe;
float wave(vec2 p,float t){return sin(p.x*5.3+t)*cos(p.y*4.7-t*.63)*.6+sin(p.y*8.1+p.x*2.3+t*.4)*.25;}
void main(){
 vec2 uv=gl_FragCoord.xy/uSize;float aspect=uSize.x/max(uSize.y,1.);
 vec2 p=(uv-.5)*vec2(aspect,1.);p+=(uPointer-.5)*.035;p.x*=.83;
 float t=uTime*.24;
 vec2 q=p+vec2(wave(p.yx*1.5,t),wave(p*1.8,-t*.8))*.07*uDistortion;
 float a=atan(q.y,q.x),r=length(q);
 float contour=.30+(sin(a*3.+t)*.023+cos(a*5.-t*.6)*.012)*uDistortion;
 float d1=abs(r-contour),d2=abs(r-contour-.045-wave(q*2.,t)*.014*uDistortion);
 float arc=.5+.5*smoothstep(-.6,.8,sin(a*2.+t*.5));
 float core=exp(-d1*145.)*arc,fringe=exp(-d2*31.)*(.6+.4*cos(a-t));
 float bloom=exp(-d1*21.)*.3,inside=exp(-r*r*9.)*.06;
 vec3 color=mix(uPaper,uFringe,clamp((fringe*.44+bloom+inside)*uIntensity,0.,.88));
 color=mix(color,uCore,clamp(core*.9*uIntensity,0.,1.));
 float fine=sin(gl_FragCoord.x*1.71+gl_FragCoord.y*2.13)*.002;
 gl_FragColor=vec4(clamp(color+fine,0.,1.),1.);
}`;
