    },
    onPointerLeave: reset,
    onFocus() { focused.current = true; if (enabled && !quiet) lift.set(.6); },
    onBlur(event: React.FocusEvent<HTMLElement>) {
      if (!event.currentTarget.contains(event.relatedTarget)) { focused.current = false; reset(); }
    },
  };
}

